@sealed
class SettingsTransportImpl extends RustOpaque implements SettingsTransport {
  // Not to be used by end users
  SettingsTransportImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  SettingsTransportImpl.frbInternalSseDecode(
    BigInt ptr,
    int externalSizeOnNative,
  ) : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_SettingsTransport,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_SettingsTransport,
    rustArcDecrementStrongCountPtr: RustLib
        .instance
        .api
        .rust_arc_decrement_strong_count_SettingsTransportPtr,
  );

  /// Measure this device's StemgenRT hop cost on the CPU EP.
  ///
  /// Ensures the model is on disk first (downloading it if needed), then runs
  /// a warm-up plus `DEFAULT_BENCH_HOPS` timed hops on a private CPU session.
  /// It never starts the live producer and never touches playback state, and
  /// it runs on the FRB worker thread rather than the audio callback.
  ///
  /// `sink` receives hop progress; when the stream completes, the result is
  /// available from [`Self::realtime_stems_capability`]. Nothing is persisted:
  /// the verdict lives for this session, and a newer run replaces it.
  Stream<RealtimeStemsBenchmarkProgress> benchmarkRealtimeStems() => RustLib
      .instance
      .api
      .crateApiSettingsSettingsTransportBenchmarkRealtimeStems(that: this);

  /// Clear the live override only when [mapping_id] still owns it.
  ///
  /// Avoids a read-then-clear race when another controller switched audio in
  /// between the caller reading settings and clearing.
  Future<AppSettings> clearControllerAudioOverride({
    required String mappingId,
  }) => RustLib.instance.api
      .crateApiSettingsSettingsTransportClearControllerAudioOverride(
        that: this,
        mappingId: mappingId,
      );

  /// Current session settings (schema-validated).
  Future<AppSettings> getSettings() => RustLib.instance.api
      .crateApiSettingsSettingsTransportGetSettings(that: this);

  /// Latest device benchmark for this session.
  ///
  /// `None` until the probe has run; the result is not persisted, so every
  /// launch starts unmeasured.
  Future<RealtimeStemsCapability?> realtimeStemsCapability() => RustLib
      .instance
      .api
      .crateApiSettingsSettingsTransportRealtimeStemsCapability(that: this);

  /// Apply settings. Does not restart the engine or update the library —
  /// callers apply those separately (mirrors Flutter `saveAppSettings`).
  Future<AppSettings> saveSettings({required AppSettings settings}) =>
      RustLib.instance.api.crateApiSettingsSettingsTransportSaveSettings(
        that: this,
        settings: settings,
      );

  /// Replace the live controller audio override without touching disk.
  ///
  /// Callers restart the engine afterwards so the effective buses change.
  Future<AppSettings> setControllerAudioOverride({
    ControllerAudioOverride? overrideSettings,
  }) => RustLib.instance.api
      .crateApiSettingsSettingsTransportSetControllerAudioOverride(
        that: this,
        overrideSettings: overrideSettings,
      );
}
